  entities: Record<string, string>;
};

export interface WorldProtocol {
  reset(): WorldStateHandle;
  applyOperation(
    state: WorldStateHandle,
    operationDisplayName: string
  ): { success: true; newState: WorldStateHandle } | { success: false; error: string };
  getEntityState(state: WorldStateHandle, entityDisplayName: string): string;
  toAbstractSnapshot(state: WorldStateHandle): Record<string, string>;
}

const INITIAL_ENTITY_STATE: Record<string, string> = {
  Zef: "idle",
  Tal: "idle",
};

function copyState(state: WorldStateHandle): WorldStateHandle {
  return { entities: { ...state.entities } };
}

function isWorldStateHandle(state: WorldStateHandle): boolean {
  return Boolean(state && state.entities && typeof state.entities === "object");
}

export const protocol: WorldProtocol = {
  reset(): WorldStateHandle {
    return { entities: { ...INITIAL_ENTITY_STATE } };
  },

  applyOperation(state, operationDisplayName) {
    if (!isWorldStateHandle(state)) {
      return { success: false, error: "Invalid world state" };
    }

    const newState = copyState(state);

    switch (operationDisplayName) {
      case "kindleZef":
        newState.entities.Zef = "pex";
        return { success: true, newState };
      case "kindleTal":
        newState.entities.Tal = "pex";
        return { success: true, newState };
      case "kindleBoth":
        newState.entities.Zef = "pex";
        newState.entities.Tal = "pex";
        return { success: true, newState };
      default:
        return {
          success: false,
          error: `Unknown operation: ${operationDisplayName}`,
        };
    }
  },

  getEntityState(state, entityDisplayName) {
    if (!isWorldStateHandle(state)) {
      return "unknown";
    }
    return state.entities[entityDisplayName] ?? "unknown";
  },

  toAbstractSnapshot(state) {
    if (!isWorldStateHandle(state)) {
      return {};
    }
    return { ...state.entities };
  },
};
"}],"workingNote":"Added the atomic kindleBoth transition. It immutably clones the world state and sets both Zef and Tal to pex, while retaining the existing single-entity kindle transitions and protocol surface."}

